package main

import (
    "flag"
    "fmt"
    "io"
    "os"
)

const usage = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

type options struct {
    help, version, all, pass, skip, notests, small, noColor bool
    follow, timestamp, progress bool
    slow int
    sort, format, file, followFile, compare, trim string
}

func main() { os.Exit(execute()) }

func execute() int {
    var o options
    f := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
    f.SetOutput(os.Stderr)
    f.Usage = func() { fmt.Fprint(f.Output(), usage) }
    f.BoolVar(&o.help, "h", false, "")
    f.BoolVar(&o.help, "help", false, "")
    f.BoolVar(&o.version, "v", false, "")
    f.BoolVar(&o.version, "version", false, "")
    f.BoolVar(&o.all, "all", false, "")
    f.BoolVar(&o.pass, "pass", false, "")
    f.BoolVar(&o.skip, "skip", false, "")
    f.BoolVar(&o.notests, "notests", false, "")
    f.BoolVar(&o.small, "smallscreen", false, "")
    f.BoolVar(&o.noColor, "nocolor", false, "")
    f.BoolVar(&o.follow, "follow", false, "")
    f.BoolVar(&o.timestamp, "include-timestamp", false, "")
    f.BoolVar(&o.progress, "progress", false, "")
    f.IntVar(&o.slow, "slow", 0, "")
    f.StringVar(&o.sort, "sort", "name", "")
    f.StringVar(&o.format, "format", "basic", "")
    f.StringVar(&o.file, "file", "", "")
    f.StringVar(&o.followFile, "follow-output", "", "")
    f.StringVar(&o.compare, "compare", "", "")
    f.StringVar(&o.trim, "trimpath", "", "")
    if err := f.Parse(os.Args[1:]); err != nil { return 2 }
    if o.version { fmt.Println("tparse version: (devel)"); return 0 }
    if o.help { fmt.Print(usage); return 0 }
    if o.format != "basic" && o.format != "plain" && o.format != "markdown" {
        fmt.Fprintf(os.Stderr, "invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", o.format)
        return 0
    }
    if o.sort != "name" && o.sort != "elapsed" && o.sort != "cover" {
        fmt.Fprintf(os.Stderr, "invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", o.sort)
        return 0
    }
    if _, set := os.LookupEnv("NO_COLOR"); set { o.noColor = true }
    var follow io.Writer
    if o.follow { follow = os.Stdout }
    if o.followFile != "" {
        out, err := os.Create(o.followFile)
        if err != nil { fmt.Fprintln(os.Stderr, err); return 0 }
        defer out.Close()
        follow = out
    }
    var input io.Reader = os.Stdin
    if o.file != "" {
        in, err := os.Open(o.file)
        if err != nil { fmt.Fprintln(os.Stderr, err); return 1 }
        defer in.Close()
        input = in
    }
    r := renderer{o:o, out:os.Stdout}
    data, err := readEvents(input, &r, follow)
    if err != nil { fmt.Fprintln(os.Stderr, err); return 1 }
    var before *testRun
    if o.compare != "" {
        in, err := os.Open(o.compare)
        if err != nil {
            fmt.Fprintf(os.Stderr, "warning: failed to open against file: %s\n", o.compare)
        } else {
            before, err = readEvents(in, nil, nil)
            in.Close()
            if err != nil { fmt.Fprintf(os.Stderr, "warning: failed to parse against file: %s\n", o.compare) }
        }
    }
    r.render(data, before)
    return data.exitCode()
}
EOF
cat > events.go <<'EOF'
package main

import (
    "bufio"
    "encoding/json"
    "errors"
    "fmt"
    "io"
    "regexp"
    "sort"
    "strconv"
    "strings"
    "time"
)

// The stream is reduced into package metadata and ordered, named test records.
// Test status and timing come from completion events; output is accumulated
// independently so that a late log message cannot change a completed test.
type event struct {
    Time time.Time
    Action string
    Package string
    Test string
    Elapsed float64
    Output string
}

type testResult struct {
    event event
    output string
    heading string
}

type packageResult struct {
    key string
    event event
    tests []*testResult
    byName map[string]*testResult
    noTests string
    cached bool
    cover float64
    hasCover bool
    panic bool
    panicTest string
    panicOutput string
    buildFail bool
    buildReason string
}

type testRun struct {
    packages map[string]*packageResult
    ordered []*packageResult
}

func newRun() *testRun { return &testRun{packages:map[string]*packageResult{}} }
func (d *testRun) pkg(name string) *packageResult {
    if p := d.packages[name]; p != nil { return p }
    p := &packageResult{key:name, byName:map[string]*testResult{}}
    d.packages[name] = p
    d.ordered = append(d.ordered, p)
    return p
}

var noEvents = errors.New("no parsable events: Make sure to run go test with -json flag")
var buildLine = regexp.MustCompile(`^FAIL\s+(\S+)\s+\[([^\]]+)\]`)
var coverPattern = regexp.MustCompile(`[0-9]+\.[0-9]% of statements`)
var hiddenOutput = regexp.MustCompile(`(?:=== (?:RUN|PAUSE|CONT)\s|--- (?:PASS|SKIP):)`)
var failHeading = regexp.MustCompile(`(?s)( *)(--- FAIL:.*)`)

func readEvents(input io.Reader, r *renderer, follow io.Writer) (*testRun, error) {
    d := newRun()
    scanner := bufio.NewScanner(input)
    started := false
    for scanner.Scan() {
        line := scanner.Text()
        var e event
        if err := json.Unmarshal([]byte(line), &e); err != nil {
            if started { return nil, noEvents }
            if follow != nil { fmt.Fprintln(follow, line) }
            if match := buildLine.FindStringSubmatch(line); match != nil {
                p := d.pkg(match[1])
                p.buildFail = true
                p.buildReason = match[2]
                p.event = event{Package:match[1], Action:"fail"}
            }
            continue
        }
        started = true
        p := d.pkg(e.Package)
        if follow != nil && e.Output != "" && !isHidden(e) {
            if r != nil && r.o.timestamp { fmt.Fprintf(follow, "%s ", e.Time.Format(time.RFC3339)) }
            fmt.Fprint(follow, e.Output)
        }
        if r != nil && r.o.progress && isPackageEnd(e) {
            status, name := e.Action, e.Package
            if p.noTests != "" { status = "skip"; name += " ["+p.noTests+"]" }
            fmt.Fprintf(r.out, "[%s]\t%9.2fs\t%s\n", r.status(status), e.Elapsed, name)
        }
        d.add(e)
    }
    if err := scanner.Err(); err != nil { return nil, fmt.Errorf("received scanning error: %w", err) }
    if !started { return nil, noEvents }
    return d, nil
}

func isPackageEnd(e event) bool {
    return e.Test == "" && e.Output == "" && (e.Action == "pass" || e.Action == "fail")
}
func isHidden(e event) bool {
    if hiddenOutput.MatchString(e.Output) { return true }
    return e.Test == "" && (e.Output == "PASS\n" || e.Output == "FAIL\n")
}

func (d *testRun) add(e event) {
    p := d.pkg(e.Package)
    if p.panic {
        if e.Action == "output" { p.panicOutput += e.Output }
        return
    }
    if strings.HasPrefix(e.Output, "panic:") {
        p.panic = true
        p.panicTest = e.Test
        p.panicOutput = e.Output
        p.event = e
        p.event.Action = "panic"
        return
    }
    if isPackageEnd(e) {
        p.event = e
        p.buildReason = ""
        return
    }
    if e.Action == "start" { return }
    if e.Test == "" {
        if strings.HasPrefix(e.Output, "ok  ") && strings.Contains(e.Output, "(cached)") {
            p.cached = true
            return
        }
        if strings.HasPrefix(e.Output, "?   ") && strings.Contains(e.Output, "[no test files]") {
            p.noTests = "no test files"
            p.event = e
            return
        }
        if strings.HasPrefix(e.Output, "ok  ") && strings.Contains(e.Output, "[no tests to run]") {
            p.noTests = "no tests to run"
            p.event = e
            return
        }
        if strings.Contains(e.Output, "coverage:") {
            if s := coverPattern.FindString(e.Output); s != "" {
                p.cover, _ = strconv.ParseFloat(strings.SplitN(s,"%",2)[0],64)
                p.hasCover = true
            }
        }
        if e.Action == "output" { return }
        if e.Action == "skip" && p.noTests != "" { return }
    }
    t := p.byName[e.Test]
    if t == nil {
        t = &testResult{event:e}
        p.byName[e.Test] = t
        p.tests = append(p.tests,t)
    }
    if e.Action == "pass" || e.Action == "skip" || e.Action == "fail" { t.event = e }
    if e.Action == "output" && !isHidden(e) {
        if match := failHeading.FindStringSubmatch(e.Output); match != nil {
            t.heading += strings.Repeat(" ", len(match[1])/2) + strings.TrimRight(match[2], "\r\n")
        } else {
            t.output += e.Output
        }
    }
}

func testStatus(t *testResult) string {
    if t.event.Action == "pass" { return "pass" }
    if t.event.Action == "skip" { return "skip" }
    return "fail"
}
func (p *packageResult) counts() (pass, fail, skip int) {
    for _, t := range p.tests {
        switch testStatus(t) {
        case "pass": pass++
        case "skip": skip++
        default: fail++
        }
    }
    return
}
func (d *testRun) exitCode() int {
    code := 0
    for _, p := range d.ordered {
        if p.panic || p.event.Action == "fail" { if code < 1 { code = 1 } }
        if p.buildFail { code = 2 }
    }
    return code
}
func (d *testRun) sorted(by string) []*packageResult {
    result := append([]*packageResult(nil),d.ordered...)
    sort.SliceStable(result,func(i,j int) bool {
        switch by {
        case "elapsed": return result[i].event.Elapsed > result[j].event.Elapsed
        case "cover": return result[i].cover > result[j].cover
        default: return result[i].event.Package < result[j].event.Package
        }
    })
    return result
}
EOF
