package main

import (
    "fmt"
    "io"
    "path"
    "sort"
    "strings"
)

type renderer struct { o options; out io.Writer }
func (r *renderer) color(s, code string) string {
    if r.o.noColor || r.o.format=="markdown" { return s }
    return "\x1b["+code+"m"+s+"\x1b[0m"
}
func (r *renderer) status(action string) string {
    s := strings.ToUpper(action)
    code,emoji := "91","🔴"
    switch action {
    case "pass": code,emoji = "92","🟢"
    case "skip","notest": code,emoji = "93","🟡"
    }
    if r.o.format=="markdown" && !r.o.noColor { return emoji+" "+s }
    return r.color(s,code)
}
func (r *renderer) packageName(s string) string {
    s = strings.TrimPrefix(s,r.o.trim)
    if r.o.small && s!="" { s=path.Base(s) }
    return s
}
func (r *renderer) testName(s string) string {
    if !r.o.small || len(s)<=32 || !strings.Contains(s,"/") { return s }
    parts := strings.Split(s,"/")
    result := parts[0]
    for _,p := range parts[1:] {
        result += "\n /"
        first := true
        for len(p)>32 {
            if !first { result += "\n  " }
            result += p[:30]+" …"
            p=p[30:]
            first=false
        }
        if !first { result += "\n  " }
        result+=p
    }
    return result
}

func (r *renderer) box(action, name string) string {
    if r.o.format=="markdown" { return "## "+r.status(action)+" • "+name+"\n" }
    label := r.color(r.status(action),"91")
    middle := "   "+label+"  package: "+name+"   "
    w := visibleWidth(middle)
    return r.color("┏"+strings.Repeat("━",w)+"┓","38;5;103")+"\n"+
        r.color("┃","38;5;103")+middle+r.color("┃","38;5;103")+"\n"+
        r.color("┗"+strings.Repeat("━",w)+"┛","38;5;103")+"\n"
}

func (r *renderer) render(d, before *testRun) {
    pkgs := d.sorted(r.o.sort)
    if r.o.all || r.o.pass || r.o.skip { r.renderTests(pkgs) }
    for _,p := range pkgs {
        if p.panic { r.renderPanic(p); continue }
        _,fails,_ := p.counts()
        if fails > 0 { r.renderFailure(p) }
    }
    r.renderPackages(pkgs,before)
}

func (r *renderer) testRows(p *packageResult) [][]string {
    var passed, skipped, failed []*testResult
    for _,t := range p.tests {
        switch testStatus(t) {
        case "pass": passed = append(passed,t)
        case "skip": skipped = append(skipped,t)
        case "fail": failed = append(failed,t)
        }
    }
    sort.SliceStable(passed,func(i,j int) bool { return passed[i].event.Elapsed > passed[j].event.Elapsed })
    if r.o.slow>0 && len(passed)>r.o.slow { passed=passed[:r.o.slow] }
    var selected []*testResult
    if r.o.all || r.o.pass { selected=append(selected,passed...) }
    if r.o.all || r.o.skip { selected=append(selected,skipped...) }
    selected=append(selected,failed...)
    var rows [][]string
    for _,t := range selected {
        row:=[]string{r.status(testStatus(t)), fmt.Sprintf("%.2f",t.event.Elapsed),r.testName(t.event.Test)}
        if r.o.format!="markdown" { row=append(row,r.packageName(t.event.Package)) }
        rows=append(rows,row)
    }
    return rows
}
func (r *renderer) renderTests(pkgs []*packageResult) {
    var allRows [][]string
    for i,p := range pkgs {
        if p.panic || p.noTests!="" || p.buildFail { continue }
        rows := r.testRows(p)
        if r.o.format=="markdown" {
            if len(rows)==0 { continue }
            pass,fail,skip := p.counts()
            fmt.Fprintf(r.out,"## 📦 Package **`%s`**\n\nTests: ✓ %d passed | %d skipped | %d failed\n\n<details>\n\n<summary>Click for test summary</summary>\n\n",p.event.Package,pass,skip,fail)
            fmt.Fprint(r.out,makeTable([]string{"Status","Elapsed","Test"},rows,map[int]bool{2:true},r.o.format))
            fmt.Fprint(r.out,"</details>\n\n\n")
        } else {
            allRows=append(allRows,rows...)
            if i<len(pkgs)-1 { allRows=append(allRows,[]string{"","","",""}) }
        }
    }
    if r.o.format!="markdown" { fmt.Fprint(r.out,makeTable([]string{"Status","Elapsed","Test","Package"},allRows,map[int]bool{2:true,3:true},r.o.format)) }
}

func (r *renderer) renderFailure(p *packageResult) {
    fmt.Fprint(r.out,r.box(p.event.Action,p.event.Package))
    if r.o.format=="markdown" { fmt.Fprint(r.out,"\n```\n") } else { fmt.Fprint(r.out,"\n") }
    var failed []*testResult
    for _,t := range p.tests { if testStatus(t)=="fail" { failed=append(failed,t) } }
    sort.SliceStable(failed,func(i,j int) bool { return failed[i].event.Test < failed[j].event.Test })
    prevRoot := ""
    for i,t := range failed {
        root:=strings.SplitN(t.event.Test,"/",2)[0]
        if i>0 && root!=prevRoot {
            fmt.Fprintln(r.out,strings.Repeat("─",96))
            fmt.Fprintln(r.out,r.color("","2")+spaces(96))
        }
        prevRoot=root
        heading := t.heading
        if heading!="" {
            parts:=strings.Split(heading,"\n")
            w:=0
            for _,s:=range parts { if n:=visibleWidth(s);n>w { w=n } }
            for _,s:=range parts { fmt.Fprintln(r.out,r.color(s,"31")+spaces(w-visibleWidth(s))) }
        } else { fmt.Fprintln(r.out) }
        if t.output!="" { fmt.Fprint(r.out,"\n",t.output,"\n") }
    }
    if r.o.format=="markdown" { fmt.Fprint(r.out,"```\n\n") }
}

func (r *renderer) renderPanic(p *packageResult) {
    name:=p.event.Package
    if p.panicTest!="" { name+=" • "+p.panicTest }
    content:=r.box("panic",name)+strings.ReplaceAll(p.panicOutput,"\t","    ")
    parts:=strings.Split(content,"\n")
    for _,line:=range parts {
        fmt.Fprintln(r.out,line+spaces(96-visibleWidth(line)))
    }
}

func (r *renderer) renderPackages(pkgs []*packageResult, before *testRun) {
    var specials, normal, empty []*packageResult
    for _,p:=range pkgs {
        if p.panic || p.buildFail { specials=append(specials,p) } else if p.noTests!="" { empty=append(empty,p) } else { normal=append(normal,p) }
    }
    selected:=append(specials,normal...)
    if r.o.notests || len(selected)==0 { selected=append(selected,empty...) }
    var rows [][]string
    for _,p:=range selected {
        s:=p.event.Action
        if s!="pass" && s!="fail" { s="" }
        pass,fail,skip:=p.counts()
        ps,fs,ss:=fmt.Sprint(pass),fmt.Sprint(fail),fmt.Sprint(skip)
        name:=r.packageName(p.event.Package)
        if p.panic { s="panic";ps,fs,ss="--","--","--" }
        if p.buildFail { s="fail";ps,fs,ss="--","--","--";name+="\n["+p.buildReason+"]" }
        if p.noTests!="" && !p.panic && !p.buildFail { s="notest";ps,fs,ss="--","--","--";name+="\n["+p.noTests+"]" }
        elapsed:=fmt.Sprintf("%.2fs",p.event.Elapsed)
        if p.cached { elapsed="(cached)" }
        cover:="--"
        if p.hasCover {
            cover=fmt.Sprintf("%.1f%%",p.cover)
            if before!=nil {
                if old:=before.packages[p.key];old!=nil && old.hasCover {
                    diff:=p.cover-old.cover
                    if diff!=0 {
                        cover+=fmt.Sprintf(" (%+.1f%%)",diff)
                        code:="92";if diff<0 { code="91" }
                        cover=r.color(cover,code)
                    }
                }
            }
        }
        if s!="" { s=r.status(s) }
        rows=append(rows,[]string{s,elapsed,name,cover,ps,fs,ss})
    }
    fmt.Fprint(r.out,makeTable([]string{"Status","Elapsed","Package","Cover","Pass","Fail","Skip"},rows,map[int]bool{2:true},r.o.format))
}
