package main

import (
    "regexp"
    "strings"
    "unicode"
)

var ansiPattern = regexp.MustCompile("\x1b\\[[0-9;?]*[ -/]*[@-~]")

func visibleWidth(s string) int {
    s = ansiPattern.ReplaceAllString(s, "")
    n := 0
    for _, c := range s { n += runeWidth(c) }
    return n
}
func runeWidth(c rune) int {
    if c < 32 || (c >= 0x7f && c < 0xa0) || unicode.Is(unicode.Mn,c) || unicode.Is(unicode.Me,c) || unicode.Is(unicode.Cf,c) { return 0 }
    if (c>=0x1100 && c<=0x115f) || c==0x2329 || c==0x232a ||
       (c>=0x2e80 && c<=0xa4cf && c!=0x303f) || (c>=0xac00 && c<=0xd7a3) ||
       (c>=0xf900 && c<=0xfaff) || (c>=0xfe10 && c<=0xfe19) ||
       (c>=0xfe30 && c<=0xfe6f) || (c>=0xff00 && c<=0xff60) ||
       (c>=0xffe0 && c<=0xffe6) || (c>=0x1f300 && c<=0x1faff) ||
       (c>=0x20000 && c<=0x3fffd) { return 2 }
    return 1
}
func spaces(n int) string { if n <= 0 { return "" }; return strings.Repeat(" ",n) }
func align(s string, width int, center bool) string {
    n := width-visibleWidth(s)
    if n < 0 { n = 0 }
    if center { return spaces(n/2)+s+spaces(n-n/2) }
    return s+spaces(n)
}

// A table is laid out before it is rendered. All formats share cell sizes and
// alignment; only their borders and row separators differ.
func makeTable(headers []string, rows [][]string, left map[int]bool, format string) string {
    if len(rows)==0 { return "" }
    widths := make([]int,len(headers))
    for i,h := range headers { widths[i] = visibleWidth(h) }
    prepared := make([][][]string,len(rows))
    for i,row := range rows {
        prepared[i] = make([][]string,len(headers))
        for j := range headers {
            s := ""
            if j < len(row) { s = strings.ReplaceAll(row[j],"\t","    ") }
            ls := strings.Split(s,"\n")
            prepared[i][j] = ls
            for _,v := range ls { if w := visibleWidth(v); w > widths[j] { widths[j] = w } }
        }
    }
    var b strings.Builder
    border := func(start,mid,end,bar string) {
        b.WriteString(start)
        for i,w := range widths { if i>0 { b.WriteString(mid) }; b.WriteString(strings.Repeat(bar,w+2)) }
        b.WriteString(end); b.WriteByte('\n')
    }
    row := func(values []string, header bool) {
        sep := "│"
        if format=="markdown" { sep = "|" }; if format=="plain" { sep=" " }
        b.WriteString(sep)
        for j := range headers {
            b.WriteByte(' ')
            b.WriteString(align(values[j], widths[j], header || !left[j]))
            b.WriteByte(' '); b.WriteString(sep)
        }
        b.WriteByte('\n')
    }
    if format=="basic" { border("╭","┬","╮","─") }
    row(headers,true)
    switch format {
    case "basic": border("├","┼","┤","─")
    case "markdown": border("|","|","|","-")
    case "plain": border(" "," "," "," ")
    }
    for _,cells := range prepared {
        height := 1
        for _,ls := range cells { if len(ls)>height { height = len(ls) } }
        for line:=0; line<height; line++ {
            values := make([]string,len(headers))
            for j,ls := range cells { if line<len(ls) { values[j]=ls[line] } }
            row(values,false)
        }
    }
    if format=="basic" { border("╰","┴","╯","─") }
    return b.String()
}
