package main

import (
    "bytes"
    "encoding/json"
    "strings"
    "testing"
)

func stream(events ...event) string {
    var out strings.Builder
    encoder:=json.NewEncoder(&out)
    for _,e:=range events { _=encoder.Encode(e) }
    return out.String()
}

func TestCompletionAndMaximumElapsed(t *testing.T) {
    input:=stream(
        event{Action:"start",Package:"example/pkg"},
        event{Action:"run",Package:"example/pkg",Test:"TestOne"},
        event{Action:"pass",Package:"example/pkg",Test:"TestOne",Elapsed:2.5},
        event{Action:"run",Package:"example/pkg",Test:"TestOne"},
        event{Action:"output",Package:"example/pkg",Test:"TestOne",Output:"a message\n"},
        event{Action:"fail",Package:"example/pkg",Test:"TestOne",Elapsed:1.2},
        event{Action:"fail",Package:"example/pkg",Elapsed:3.7},
    )
    d,err:=readEvents(strings.NewReader(input),nil,nil)
    if err!=nil {t.Fatal(err)}
    p:=d.packages["example/pkg"]
    if len(p.tests)!=1 || testStatus(p.tests[0])!="fail" || p.tests[0].event.Elapsed!=2.5 {
        t.Fatalf("incorrect repeated-test reduction: %+v",p.tests)
    }
    if p.tests[0].output!="a message\n" || d.exitCode()!=1 {t.Fatal("lost output or failure status")}
}

func TestSimpleSummary(t *testing.T) {
    d,err:=readEvents(strings.NewReader(stream(event{Action:"pass",Package:"demo",Elapsed:1.234})),nil,nil)
    if err!=nil {t.Fatal(err)}
    var output bytes.Buffer
    r:=renderer{o:options{format:"basic",sort:"name",noColor:true},out:&output}
    r.render(d,nil)
    expected:="╭────────┬─────────┬─────────┬───────┬──────┬──────┬──────╮\n"+
        "│ Status │ Elapsed │ Package │ Cover │ Pass │ Fail │ Skip │\n"+
        "├────────┼─────────┼─────────┼───────┼──────┼──────┼──────┤\n"+
        "│  PASS  │  1.23s  │ demo    │  --   │  0   │  0   │  0   │\n"+
        "╰────────┴─────────┴─────────┴───────┴──────┴──────┴──────╯\n"
    if output.String()!=expected {t.Fatalf("summary mismatch:\n%s",output.String())}
}

func TestPreambleAndMalformedEvent(t *testing.T) {
    var followed,progress bytes.Buffer
    r:=renderer{o:options{format:"basic",noColor:true,progress:true},out:&progress}
    valid:=stream(event{Action:"pass",Package:"demo"})
    d,err:=readEvents(strings.NewReader("build diagnostic\n"+valid),&r,&followed)
    if err!=nil || d.exitCode()!=0 {t.Fatalf("preamble: %v",err)}
    if followed.String()!="build diagnostic\n" {t.Fatalf("preamble not followed: %q",followed.String())}
    if progress.String()!="[PASS]\t     0.00s\tdemo\n" {t.Fatalf("progress: %q",progress.String())}
    _,err=readEvents(strings.NewReader(valid+"bad data\n"),nil,nil)
    if err!=noEvents {t.Fatalf("malformed event should invalidate the summary: %v",err)}
    _,err=readEvents(strings.NewReader(stream(event{Action:"output",Package:"demo",Output:"=== RUN   TestX\n"})),nil,nil)
    if err==nil || err.Error()!="found no go test packages" {t.Fatalf("filtered-only input: %v",err)}
}

func TestFollowFiltersAndTimestamps(t *testing.T) {
    input:=stream(
        event{Action:"run",Package:"demo",Test:"TestX"},
        event{Action:"output",Package:"demo",Test:"TestX",Output:"=== RUN   TestX\n"},
        event{Action:"output",Package:"demo",Test:"TestX",Output:"hello\n"},
        event{Action:"output",Package:"demo",Test:"TestX",Output:"--- PASS: TestX (0.00s)\n"},
        event{Action:"pass",Package:"demo",Test:"TestX"},
        event{Action:"pass",Package:"demo"},
    )
    var followed bytes.Buffer
    r:=renderer{o:options{timestamp:true},out:&bytes.Buffer{}}
    _,err:=readEvents(strings.NewReader(input),&r,&followed)
    if err!=nil {t.Fatal(err)}
    if followed.String()!="0001-01-01T00:00:00Z hello\n" {t.Fatalf("follow: %q",followed.String())}
}

func TestPanicAndNoTestMetadata(t *testing.T) {
    d,err:=readEvents(strings.NewReader(stream(
        event{Action:"output",Package:"empty",Output:"?   \tempty\t[no test files]\n"},
        event{Action:"skip",Package:"empty"},
