    "testing"
)

func stream(events ...event) string {
    var out strings.Builder
    encoder:=json.NewEncoder(&out)
    for _,e:=range events { _=encoder.Encode(e) }
    return out.String()
}

func TestCompletionAndMaximumElapsed(t *testing.T) {
    input:=stream(
        event{Action:"start",Package:"example/pkg"},
        event{Action:"run",Package:"example/pkg",Test:"TestOne"},
        event{Action:"pass",Package:"example/pkg",Test:"TestOne",Elapsed:2.5},
        event{Action:"run",Package:"example/pkg",Test:"TestOne"},
        event{Action:"output",Package:"example/pkg",Test:"TestOne",Output:"a message\n"},
        event{Action:"fail",Package:"example/pkg",Test:"TestOne",Elapsed:1.2},
        event{Action:"fail",Package:"example/pkg",Elapsed:3.7},
    )
    d,err:=readEvents(strings.NewReader(input),nil,nil)
    if err!=nil {t.Fatal(err)}
    p:=d.packages["example/pkg"]
    if len(p.tests)!=1 || testStatus(p.tests[0])!="fail" || p.tests[0].event.Elapsed!=2.5 {
        t.Fatalf("incorrect repeated-test reduction: %+v",p.tests)
    }
    if p.tests[0].output!="a message\n" || d.exitCode()!=1 {t.Fatal("lost output or failure status")}
}

