    expected:="╭────────┬─────────┬─────────┬───────┬──────┬──────┬──────╮\n"+
        "│ Status │ Elapsed │ Package │ Cover │ Pass │ Fail │ Skip │\n"+
        "├────────┼─────────┼─────────┼───────┼──────┼──────┼──────┤\n"+
